// This is a simple interface which specifies echo.Route addition functions which
// are present on both echo.Echo and echo.Group, since we want to allow using
// either of them for path registration
type EchoRouter interface {
	CONNECT(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	DELETE(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	GET(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	HEAD(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	OPTIONS(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	PATCH(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	POST(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	PUT(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	TRACE(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
}

// RegisterHandlers adds each server route to the EchoRouter.
func RegisterHandlers(router EchoRouter, si ServerInterface) {
	RegisterHandlersWithBaseURL(router, si, "")
}

// Registers handlers, and prepends BaseURL to the paths, so that the paths
// can be served under a prefix.
func RegisterHandlersWithBaseURL(router EchoRouter, si ServerInterface, baseURL string) {

	wrapper := ServerInterfaceWrapper{
		Handler: si,
	}

	router.POST(baseURL+"/configservice/deregister/:deployment/:name/", wrapper.GiConfigDeregisterService)
	router.GET(baseURL+"/configservice/discover/portal/:deployment/:serviceclass", wrapper.GiDiscoverPortal)
	router.GET(baseURL+"/configservice/discover/service/:deployment/:serviceclass", wrapper.GiDiscoverService)
	router.PUT(baseURL+"/configservice/discovery/add/", wrapper.GiConfigDiscoveryAdd)
	router.GET(baseURL+"/configservice/getvalue", wrapper.GiConfigGetValue)
	router.POST(baseURL+"/configservice/instance", wrapper.GiConfigRegisterInstance)
	router.POST(baseURL+"/configservice/portal/:operation/:deployment/", wrapper.GiConfigPortal)
	router.POST(baseURL+"/configservice/putvalue", wrapper.GiConfigPutValue)
	router.GET(baseURL+"/configservice/query", wrapper.GiConfigQueryConfig)
	router.POST(baseURL+"/configservice/register", wrapper.GiConfigRegisterService)
	router.GET(baseURL+"/configservice/remove", wrapper.GiRemoveConfig)
	router.POST(baseURL+"/configservice/set", wrapper.GiConfigSetConfig)
	router.GET(baseURL+"/configservice/state/get/:deployment/:name/", wrapper.GiConfigGetState)
	router.GET(baseURL+"/configservice/state/init/:deployment/:name/:id/", wrapper.GiConfigGetInit)
	router.POST(baseURL+"/configservice/state/post/:deployment/:name/:id", wrapper.GiConfigPostState)
	router.POST(baseURL+"/configservice/store/get", wrapper.GiConfigStoreGet)
	router.POST(baseURL+"/configservice/store/put", wrapper.GiConfigStorePut)
	router.POST(baseURL+"/ginfra/datasource/init", wrapper.GiControlDatasourceInit)
	router.POST(baseURL+"/ginfra/manage/reset", wrapper.GiControlManageReset)
	router.POST(baseURL+"/ginfra/manage/stop", wrapper.GiControlManageStop)
	router.GET(baseURL+"/ginfra/specifics", wrapper.GiGetSpecifics)

}

